<section class="sc-store"><?php if(!$product){http_response_code(404);echo '<h1>Product not found</h1>';return;} $p=$product;$images=json_decode($p['product_images']??'[]',true)?:[]; ?>
<a href="<?= sc_url('products/'.rawurlencode($p['category_slug'])) ?>">← Back to collection</a><div class="sc-detail-layout"><div class="sc-gallery"><img class="sc-main-product" src="<?= sc_e(sc_image($p)) ?>" alt="<?= sc_e($p['product_name']) ?>"><?php foreach(array_slice($images,1) as $image): ?><img loading="lazy" src="<?= sc_e(sc_url('uploads/'.rawurlencode(basename($image)))) ?>" alt="<?= sc_e($p['product_name']) ?> — additional view"><?php endforeach; ?></div><div class="sc-detail-copy"><span class="sc-kicker">MADE FOR YOUR EVERYDAY</span><h1><?= sc_e($p['product_name']) ?></h1><h2><?= sc_money(sc_price($p)) ?></h2><p>Price excludes applicable tax. Shipping: ₹0.00.</p><?php if($p['product_color']): ?><p>Colour: <?= sc_e($p['product_color']) ?></p><?php endif; ?><?php if(sc_price($p)>0): ?><form method="post" action="<?= sc_url('cart') ?>"><?= sc_token() ?><input type="hidden" name="sc_action" value="cart_add"><input type="hidden" name="product_id" value="<?= (int)$p['id'] ?>"><label>Quantity<input type="number" name="quantity" min="1" max="20" value="1" required></label><button class="sc-buy" type="submit">Add to cart ↗</button></form><?php else: ?><a class="sc-buy" href="<?= sc_url('contact') ?>">Contact for availability</a><?php endif; ?><p>Need help with fit or a custom prescription? <a href="<?= sc_url('contact') ?>">Talk to our team.</a></p><?php foreach(['details'=>'Product details','technology'=>'Technology','features'=>'Features','pathology'=>'Support information'] as $field=>$title): $values=json_decode($p[$field]??'[]',true);if(!is_array($values)||!$values)continue; ?><details class="sc-product-spec"><summary><?= $title ?></summary><dl><?php foreach($values as $key=>$value): ?><dt><?= sc_e($key) ?></dt><dd><?= sc_e(is_scalar($value)?$value:json_encode($value)) ?></dd><?php endforeach; ?></dl></details><?php endforeach; ?></div></div></section>
